    // MARK: - Load Full Food Details

    @MainActor
    private func loadFoodDetails() async {
        
        // Start loading
        isLoading = true
        
        // Clear any old error
        errorMessage = ""
        
        do {
            
            // Request the full USDA food record
            foodDetails = try await foodService.fetchFoodDetails(
                fdcId: food.fdcId
            )
            
            // MARK: Debug
            print("----- USDA NUTRIENT DEBUG -----")

            print(
                "Food:",
                foodDetails?.description ?? "nil"
            )

            print(
                "Data Type:",
                foodDetails?.dataType ?? "nil"
            )

            print(
                "Nutrient Count:",
                foodDetails?.foodNutrients?.count ?? 0
            )

            for nutrient in foodDetails?.foodNutrients ?? [] {
                
                print(
                    "ID:",
                    nutrient.nutrient?.id as Any,
                    "| Name:",
                    nutrient.nutrient?.name ?? "nil",
                    "| Unit:",
                    nutrient.nutrient?.unitName ?? "nil",
                    "| Amount:",
                    nutrient.amount as Any
                )
            }
            
            print("----- USDA LABEL NUTRIENTS -----")

            print(
                "Calories:",
                foodDetails?.labelNutrients?
                    .calories?
                    .value as Any
            )

            print(
                "Protein:",
                foodDetails?.labelNutrients?
                    .protein?
                    .value as Any
            )

            print(
                "Carbohydrates:",
                foodDetails?.labelNutrients?
                    .carbohydrates?
                    .value as Any
            )

            print(
                "Fat:",
                foodDetails?.labelNutrients?
                    .fat?
                    .value as Any
            )

            print("--------------------------------")

            
            print("Full USDA food details loaded successfully.")
            
        } catch is CancellationError {
            
            print("USDA food detail request was cancelled.")
            
        } catch {
            
            errorMessage = "Could not load nutrition details."
            
            print(
                "USDA food detail request failed: \(error.localizedDescription)"
            )
        }
        
        // Stop loading
        isLoading = false
    }
    
    // MARK: - Log Food

    @MainActor
    private func logFood() async {
        
        // Clear any old message
        logMessage = ""
        
        
        // Make sure a Supabase user is logged in
        guard let currentUserID = supabase.auth.currentUser?.id else {
            
            logMessage = "You must be logged in to log food."
            return
        }
        
        
        // Make sure we successfully calculated all nutrition values
        guard let loggedCalories,
              let loggedProtein,
              let loggedCarbohydrates,
              let loggedFat else {
            
            logMessage = "Could not calculate nutrition for this serving."
            return
        }
        
        // Date formatting for time user consumed food upong logging it
        let dateFormatter = ISO8601DateFormatter()

        let consumedAtTimestamp =
            dateFormatter.string(
                from: consumedAt
            )
        
        
        // Create the food log that will be sent to Supabase
        let newFoodLog = NewFoodLog(
            
            user_id: currentUserID,
            
            source: "usda",
            
            fdc_id: food.fdcId,
            
            food_name:
                foodDetails?.description
                ?? food.description,
            
            brand_name:
                foodDetails?.brandOwner
                ?? food.brandOwner,
            
            serving_amount: servings,
            
            serving_unit: "serving",
            
            calories: loggedCalories,
            
            protein_g: loggedProtein,
            
            carbs_g: loggedCarbohydrates,
            
            fat_g: loggedFat,
            
            fiber_g: loggedFiber,

            sugar_g: loggedSugar,

            saturated_fat_g: loggedSaturatedFat,

            trans_fat_g: loggedTransFat,

            sodium_mg: loggedSodium,

            cholesterol_mg: loggedCholesterol,
            
            meal_type: mealType,
            
            consumed_at: consumedAtTimestamp
        )
        
        
        // Prevent the user from pressing Log Food repeatedly
        isLoggingFood = true
        
        defer {
            isLoggingFood = false
        }
        
        
        do {
            
            try await foodLogService.saveFoodLog(newFoodLog)
            
            logMessage = "Food logged successfully."
            
        } catch is CancellationError {
            
            print("Food logging was cancelled.")
            
        } catch {
            
            logMessage = "Could not log food."
            
            print(
                "Food logging failed: \(error.localizedDescription)"
            )
        }
    }
    
    // MARK: - Serving Amount for Nutrition Calculation

    private var servingAmountForCalculation: Double? {
        
        guard let foodDetails else {
            return nil
        }
        
        
        // Use the serving size USDA provides
        if let servingSize = foodDetails.servingSize,
           let servingUnit = foodDetails.servingSizeUnit?
                .lowercased() {
            
            switch servingUnit {
                
            // Gram-based foods
            case "g", "gram", "grams", "grm":
                return servingSize
                
            // Ounce-based foods
            case "oz", "ounce", "ounces", "onz":
                return servingSize * 28.3495
                
            // Milliliter-based foods
            case "ml", "mlt", "milliliter", "milliliters":
                return servingSize
                
            default:
                break
            }
        }
        
        
        
        
        // If there is no direct serving size,
        // find the first USDA portion with a valid gram weight
        if let gramWeight = foodDetails.foodPortions?
            .compactMap({ $0.gramWeight })
            .first(where: { $0 > 0 }) {
            
            return gramWeight
        }
        
        
        return nil
    }
    
    // True when USDA gave us enough information
    // to calculate nutrition for one serving
    private var canCalculateServingNutrition: Bool {
        
        servingAmountForCalculation != nil
    }
    
    // True when USDA supplied all four core nutrition values
    // required for a normal USDA food log
    private var hasRequiredCoreNutrition: Bool {
        
        calories?.amount != nil &&
        protein?.amount != nil &&
        carbohydrates?.amount != nil &&
        fat?.amount != nil
    }
    
    // True when all four required nutrition values
    // were successfully calculated and validated.
    private var hasValidCalculatedNutrition: Bool {
        
        loggedCalories != nil &&
        loggedProtein != nil &&
        loggedCarbohydrates != nil &&
        loggedFat != nil
    }
    
    // MARK: - Logged Nutrient Amount

    private func loggedNutrientAmount(
        _ nutrient: USDAFoodDetailNutrient?
    ) -> Double? {
        
        // Make sure USDA gave us a nutrient amount
        // and a usable serving amount.
        guard let amountPer100Units = nutrient?.amount,
              let servingAmountForCalculation else {
            
            return nil
        }
        
        
        // Reject invalid USDA/input values before calculating.
        guard amountPer100Units.isFinite,
              amountPer100Units >= 0,
              servingAmountForCalculation.isFinite,
              servingAmountForCalculation > 0,
              servings.isFinite,
              servings > 0 else {
            
            return nil
        }
        
        
        // Convert USDA's per-100-unit value
        // into the amount for one serving.
        let amountPerServing =
            (amountPer100Units *
             servingAmountForCalculation) / 100
        
        
        // Multiply by the number of servings selected.
        let totalAmount =
            amountPerServing * servings
        
        
        // Final safety check.
        guard totalAmount.isFinite,
              totalAmount >= 0 else {
            
            return nil
        }
        
        
        return totalAmount
    }
    
    // Calories for the servings the user selected
    private var loggedCalories: Double? {
        
        loggedNutrientAmount(calories)
    }


    // Protein for the servings the user selected
    private var loggedProtein: Double? {
        
        loggedNutrientAmount(protein)
    }


    // Carbohydrates for the servings the user selected
    private var loggedCarbohydrates: Double? {
        
        loggedNutrientAmount(carbohydrates)
    }


    // Fat for the servings the user selected
    private var loggedFat: Double? {
        
        loggedNutrientAmount(fat)
    }
    
    private var loggedFiber: Double? {
        
        loggedNutrientAmount(fiber)
    }


    private var loggedSugar: Double? {
        
        loggedNutrientAmount(sugar)
    }


    private var loggedSaturatedFat: Double? {
        
        loggedNutrientAmount(saturatedFat)
    }


    private var loggedTransFat: Double? {
        
        loggedNutrientAmount(transFat)
    }


    private var loggedSodium: Double? {
        
