    }
    
    // MARK: - Calories
    
    private var calories: USDAFoodDetailNutrient? {
        
        foodDetails?.foodNutrients?.first { nutrient in
            
            nutrient.nutrient?
                .name?
                .lowercased() == "energy"
            &&
            nutrient.nutrient?
                .unitName?
                .uppercased() == "KCAL"
        }
    }
    
    
    // MARK: - Protein
    
    private var protein: USDAFoodDetailNutrient? {
        
        foodDetails?.foodNutrients?.first { nutrient in
            
            nutrient.nutrient?
                .name?
                .lowercased() == "protein"
        }
    }
    
    // MARK: - Carbohydrates
    
    private var carbohydrates: USDAFoodDetailNutrient? {
        
        foodDetails?.foodNutrients?.first { nutrient in
            
            nutrient.nutrient?
                .name?
                .lowercased()
                .contains("carbohydrate") == true
        }
    }
    
    
    // MARK: - Fat
    
    private var fat: USDAFoodDetailNutrient? {
        
        foodDetails?.foodNutrients?.first { nutrient in
            
            let name =
                nutrient.nutrient?
                    .name?
                    .lowercased() ?? ""
            
            return name == "total lipid (fat)"
                || name == "total fat"
                || name == "total fat, nlea"
        }
    }
    
    // MARK: - Fiber

    private var fiber: USDAFoodDetailNutrient? {
        
        foodDetails?.foodNutrients?.first { nutrient in
            
            nutrient.nutrient?.id == 1079
            ||
            nutrient.nutrient?
                .name?
                .lowercased()
                .contains("fiber") == true
        }
    }


    // MARK: - Sugar

    private var sugar: USDAFoodDetailNutrient? {
        
        foodDetails?.foodNutrients?.first { nutrient in
            
            nutrient.nutrient?.id == 2000
            ||
            nutrient.nutrient?
                .name?
                .lowercased() == "total sugars"
        }
    }


    // MARK: - Saturated Fat

    private var saturatedFat: USDAFoodDetailNutrient? {
        
        foodDetails?.foodNutrients?.first { nutrient in
            
            nutrient.nutrient?.id == 1258
            ||
            nutrient.nutrient?
                .name?
                .lowercased()
                .contains("total saturated") == true
        }
    }


    // MARK: - Trans Fat

    private var transFat: USDAFoodDetailNutrient? {
        
        foodDetails?.foodNutrients?.first { nutrient in
            
            nutrient.nutrient?.id == 1257
            ||
            nutrient.nutrient?
                .name?
                .lowercased()
                .contains("total trans") == true
        }
    }


    // MARK: - Sodium

    private var sodium: USDAFoodDetailNutrient? {
        
        foodDetails?.foodNutrients?.first { nutrient in
            
            nutrient.nutrient?.id == 1093
            ||
            nutrient.nutrient?
                .name?
                .lowercased() == "sodium, na"
        }
    }


    // MARK: - Cholesterol

    private var cholesterol: USDAFoodDetailNutrient? {
        
        foodDetails?.foodNutrients?.first { nutrient in
            
            nutrient.nutrient?.id == 1253
            ||
            nutrient.nutrient?
                .name?
                .lowercased() == "cholesterol"
        }
    }
    
    
    // MARK: - Nutrient Text
    
    private func nutrientText(
        _ nutrient: USDAFoodDetailNutrient?
    ) -> String {
        
        guard let nutrient else {
            return "--"
        }
        
        
        let unit =
            nutrient.nutrient?
                .unitName?
                .lowercased() ?? ""
        
        
        // If USDA gave us enough serving information,
        // show nutrition for the user's selected serving.
        if canCalculateServingNutrition,
           let calculatedAmount =
                loggedNutrientAmount(nutrient) {
            
            return """
            \(calculatedAmount.formatted()) \(unit)
            """
        }
        
        
        // If USDA's serving information is incomplete,
        // fall back to the raw USDA nutrient value.
        guard let rawAmount = nutrient.amount else {
            return "--"
        }
        
        return "\(rawAmount.formatted()) \(unit)"
    }
    
    // MARK: - Nutrient Row
    
    private func nutrientRow(
        title: String,
        nutrient: USDAFoodDetailNutrient?
    ) -> some View {
        
        HStack {
            
            Text(title)
            
            Spacer()
            
            Text(nutrientText(nutrient))
                .fontWeight(.semibold)
        }
    }
